// Берём последнюю строку сводки — её только что записал Dashboard Builder.
const items = $input.all();
const item = items[items.length - 1].json;

// В таблице разбивки хранятся строкой JSON: {"RemoteOK":409,"HackerNews":140}.
// В сообщение это попадать не должно — разворачиваем в список.
const RU_LEVEL = {
  Unknown: 'не указан',
  'Not Specified': 'не указан',
  Junior: 'Junior',
  Middle: 'Middle',
  Senior: 'Senior',
};

function parse(raw) {
  try {
    return typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
  } catch (e) {
    return null;   // формат неожиданный — покажем как есть
  }
}

function breakdown(raw, dict) {
  const obj = parse(raw);
  if (!obj) return String(raw || '—');
  const rows = Object.entries(obj).sort((a, b) => b[1] - a[1]);
  if (!rows.length) return '—';
  const total = rows.reduce((s, r) => s + r[1], 0);
  return rows
    .map(([k, v]) => {
      const name = (dict && dict[k]) || k;
      const share = total ? Math.round(100 * v / total) : 0;
      return '• ' + name + ' — ' + v + ' (' + share + '%)';
    })
    .join('\n');
}

// Навыки приходят строкой «sql (120), python (98), ...» — разбираем на список.
function skillList(raw) {
  const parts = String(raw || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!parts.length) return '—';
  return parts.slice(0, 10).map((p, i) => (i + 1) + '. ' + p).join('\n');
}

const total = Number(item.total_jobs) || 0;
const remoteShare = total ? Math.round(100 * Number(item.remote_jobs) / total) : 0;

// Уровни и навыки сводка считает только по техническим вакансиям, поэтому
// сумма уровней и есть их число. Отдельной колонки в таблице для этого нет.
const levels = parse(item.levels_breakdown) || {};
const tech = Object.values(levels).reduce((s, v) => s + Number(v || 0), 0);
const techShare = total ? Math.round(100 * tech / total) : 0;

const reportText = `📊 *Еженедельный отчёт: рынок труда*
📅 Дата среза: ${String(item.date).slice(0, 10)}

🔹 *Основные метрики*
• Собрано вакансий: *${total}*
• Из них технических: *${tech}* (${techShare}%)
• Удалённая работа: *${item.remote_jobs}* (${remoteShare}%)

📈 *Топ навыков* (по техническим вакансиям)
${skillList(item.top_skills)}

📌 *Источники*
${breakdown(item.sources_breakdown)}

🎯 *Уровни* (по техническим вакансиям)
${breakdown(item.levels_breakdown, RU_LEVEL)}`;

return { json: { reportText } };
